plt.plot(t, Vendite, color="black")
plt.plot(np.arange(1, 26), lineare.predict(nuovi), "o-", color="black", markerfacecolor="none", markersize=4)
plt.axvline(24, linestyle="--", color="black")
plt.title("Extrapolation")
plt.show()
```

